# 节点池成本估算（基于 AWS EC2 pricing）
# CPU cost: $0.0236/vCPU-hour (m5.xlarge)
# Memory cost: $0.0059/GiB-hour

# 节点池月度成本
sum by (node_pool) (
  count by (node_pool) (
    kube_node_labels{label_node_pool!=""}
  ) * 0.0236 * 24 * 30  # CPU
) + sum by (node_pool) (
  sum by (node_pool, memory) (
    kube_node_status_allocatable{resource="memory"} / 1024
  ) * 0.0059 * 24 * 30  # Memory
)
